contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint v0, uint v1) public payable {
        require(v0 != v1);
        c.SetMinSum(v0); if (__ESBMC_reverted()) return;   // set a known pre-initialization value
        c.Initialized(); if (__ESBMC_reverted()) return;   // establish the state the difference needs
        bool reverted; c.SetMinSum(v1); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }   // boundary
        assert(c.MinSum() == v0);
    }
    receive() external payable {}
}

