pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 v0, uint256 v1) internal {
        vm.assume(v0 != v1);
        try c.SetMinSum(v0) {} catch { return; }
        try c.Initialized() {} catch { return; }
        bool reverted;
        try c.SetMinSum(v1) { reverted = false; } catch { reverted = true; }
        assertTrue(c.MinSum() == v0);
    }

    function testFuzz_run(uint256 v0, uint256 v1) public {
        _run(v0, v1);
    }

    receive() external payable {}
}
